private fun showDeadlineNotification(context: Context) {
    if (Build.VERSION.SDK_INT >= 33 &&
        ActivityCompat.checkSelfPermission(context, Manifest.permission.POST_NOTIFICATIONS) != PackageManager.PERMISSION_GRANTED
    ) {
        Toast.makeText(context, "Concede permiso de notificaciones para recibir recordatorios", Toast.LENGTH_SHORT).show()
        return
        // --- SECTION D: RECURSOS CULTURALES Y RADIO ---
        item {
            Card(
                colors = CardDefaults.cardColors(containerColor = InstitutionalColors.White),
                border = androidx.compose.foundation.BorderStroke(1.dp, InstitutionalColors.Border)
            ) {
                Column(Modifier.padding(18.dp), verticalArrangement = Arrangement.spacedBy(16.dp)) {
                    Text("Recursos Culturales y Audiovisuales", fontSize = 18.sp, fontWeight = FontWeight.Bold)
                    
                    // Museo
                    Card(
                        colors = CardDefaults.cardColors(containerColor = InstitutionalColors.Background),
                        modifier = Modifier.fillMaxWidth()
                    ) {
                        Column(Modifier.padding(14.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                            Row(verticalAlignment = Alignment.CenterVertically) {
                                Icon(Icons.Default.Museum, null, tint = InstitutionalColors.Green)
                                Spacer(Modifier.width(8.dp))
                                Text("Museo Histórico de Carabineros", fontWeight = FontWeight.Bold, color = InstitutionalColors.GreenDark)
                            }
                            Text(
                                "Recursos culturales, educativos y didácticos para enriquecer tu conocimiento institucional.",
                                fontSize = 12.sp,
                                color = InstitutionalColors.Graphite
                            )
                            Button(
                                onClick = {
                                    val intent = Intent(Intent.ACTION_VIEW, Uri.parse("https://www.museocarabineros.cl/web/sitio"))
                                    if (intent.resolveActivity(context.packageManager) != null) {
                                        context.startActivity(intent)
                                    }
                                },
                                modifier = Modifier.align(Alignment.End),
                                colors = ButtonDefaults.buttonColors(containerColor = InstitutionalColors.Green)
                            ) {
                                Icon(Icons.Default.Language, null, modifier = Modifier.size(16.dp))
                                Spacer(Modifier.width(6.dp))
                                Text("Visitar Sitio Web", fontSize = 12.sp)
                            }
                        }
                    }

                    // Radio
                    Card(
                        colors = CardDefaults.cardColors(containerColor = InstitutionalColors.Background),
                        modifier = Modifier.fillMaxWidth()
                    ) {
                        Column(Modifier.padding(14.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                            Row(verticalAlignment = Alignment.CenterVertically) {
                                Icon(Icons.Default.Radio, null, tint = InstitutionalColors.Navy)
                                Spacer(Modifier.width(8.dp))
                                Text("Radio Carabineros de Chile", fontWeight = FontWeight.Bold, color = InstitutionalColors.Navy)
                            }
                            Text(
                                "Sintoniza la radio oficial a través de sus frecuencias para estar informado.",
                                fontSize = 12.sp,
                                color = InstitutionalColors.Graphite
                            )
                            Row(horizontalArrangement = Arrangement.spacedBy(12.dp)) {
                                Surface(
                                    color = InstitutionalColors.Navy.copy(alpha = 0.1f),
                                    shape = RoundedCornerShape(8.dp)
                                ) {
                                    Text("FM: 98.1", Modifier.padding(horizontal = 10.dp, vertical = 6.dp), fontWeight = FontWeight.Bold, color = InstitutionalColors.Navy)
                                }
                                Surface(
                                    color = InstitutionalColors.Navy.copy(alpha = 0.1f),
                                    shape = RoundedCornerShape(8.dp)
                                ) {
                                    Text("AM: 820", Modifier.padding(horizontal = 10.dp, vertical = 6.dp), fontWeight = FontWeight.Bold, color = InstitutionalColors.Navy)
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    val notification = NotificationCompat.Builder(context, "deadlines")
        .setSmallIcon(android.R.drawable.ic_dialog_info)
        .setContentTitle("Tutor Virtual ESUCAR")
        .setContentText("Recuerda revisar tus hitos académicos para tu Trabajo de Título.")
        .setPriority(NotificationCompat.PRIORITY_DEFAULT)
        .setAutoCancel(true)
        .build()

    NotificationManagerCompat.from(context).notify(1001, notification)
}
